    pub const VT_SIGMA_C_KM: ::flatbuffers::VOffsetT = 36;
    pub const VT_SIGMA_SEPARATION_KM: ::flatbuffers::VOffsetT = 38;
    pub const VT_BAND3_R_KM: ::flatbuffers::VOffsetT = 40;
